tokens:
--scheme: dark;
color-scheme: dark;
--bg: #0c0806;
--bg2: #140e0a;
--surface: #1d140f;
--surface2: #271b14;
--ink: #f6efe6;
--muted: #d4c3b0;
--faint: #a89682;
--cardmeta: #e6d8c8;
--gold: #f2b852;
--gold-soft: #fbe0a2;
--gold-deep: #946618;
--on-gold: #160e02;
--ink-soft: #d4c3b0;
--line: rgba(242, 184, 82, 0.14);
--line-strong: rgba(242, 184, 82, 0.48);
--ok: #7fe3a8;
--warn: #f5c96b;
--bad: #ff8a7a;
--shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 18px 50px rgba(0, 0, 0, 0.78);
--elev-1: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 2px 8px rgba(0, 0, 0, 0.52);
--elev-2: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 12px 30px rgba(0, 0, 0, 0.64);
--elev-3: inset 0 1px 0 rgba(255, 255, 255, 0.10), 0 28px 80px rgba(0, 0, 0, 0.82);
--scrim: rgba(4, 6, 8, 0.76);
--focus: #fbe0a2;
--th-bg: #271b14;
--tabgrad1: #271b14; --tabgrad2: #1d140f;
--toastgrad1: #271b14; --toastgrad2: #1d140f;
--foot-bg: rgba(7, 9, 11, 0.92);
--drawerbar-bg: rgba(16, 20, 24, 0.94);
--ph-bg: #271b14;
--sel-bg: rgba(242, 184, 82, 0.16);
--row-hover: rgba(242, 184, 82, 0.07);
