extra_css:
/* Sahel Futurism surfaces: scoped to html[data-atmo="sahel"] only. */
html[data-atmo="sahel"] .card, html[data-atmo="sahel"] .panel, html[data-atmo="sahel"] .gx-card {
  background: radial-gradient(125% 80% at 50% 0%, rgba(242, 184, 82,.08), transparent 62%), linear-gradient(180deg, #271b14e0, #0c0806f2);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(242, 184, 82,.30), inset 0 0 0 1px rgba(242, 184, 82,.22), 0 18px 46px rgba(0,0,0,.78);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="sahel"] .card:hover, html[data-atmo="sahel"] .gx-card:hover {
  transform: translateY(-2px);
  box-shadow: inset 0 1px 0 rgba(242, 184, 82,.52), inset 0 0 0 1px rgba(242, 184, 82,.46), 0 0 28px rgba(242, 184, 82,.14), 0 22px 54px rgba(0,0,0,.82); }
html[data-atmo="sahel"] h1, html[data-atmo="sahel"] h2 { background: linear-gradient(180deg, #ffffff, #fbe0a2 50%, #f2b852); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="sahel"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

